#define MAX_BITMAP_BUF_SIZE (16 * 1024) /* 16K */
#define TS_MONITOR_ATTRIBUTES_SIZE 20 /* [MS-RDPBCGR] 2.2.1.3.9 */

/******************************************************************************/
struct xrdp_session *EXPORT_CC
libxrdp_init(struct xrdp_process *id, struct trans *trans, const char *xrdp_ini)
{
    struct xrdp_session *session;

    session = (struct xrdp_session *)g_malloc(sizeof(struct xrdp_session), 1);
    session->id = id;
    session->trans = trans;
    if (xrdp_ini != NULL)
    {
        session->xrdp_ini = g_strdup(xrdp_ini);
    }
    else
    {
        session->xrdp_ini = g_strdup(XRDP_CFG_PATH "/xrdp.ini");
    }
    session->rdp = xrdp_rdp_create(session, trans);
    session->orders = xrdp_orders_create(session, session->rdp);
    session->client_info = &session->rdp->client_info;
    session->check_for_app_input = 1;
    return session;
}

/******************************************************************************/
int EXPORT_CC
libxrdp_exit(struct xrdp_session *session)
{
    if (session == 0)
    {
        return 0;
    }

    xrdp_orders_delete(session->orders);
    xrdp_rdp_delete(session->rdp);
    g_free(session->xrdp_ini);
    g_free(session);
    return 0;
}

/******************************************************************************/
int EXPORT_CC
libxrdp_disconnect(struct xrdp_session *session, int errinfo)
{
    int rv = 0;
    struct trans *trans = NULL;
    struct xrdp_rdp *rdp = NULL;
    int early_capability_flags = 0;

    if (session != NULL)
    {
        trans = session->trans;
        rdp = session->rdp;
        if (session->client_info != NULL)
        {
            early_capability_flags =
                session->client_info->mcs_early_capability_flags;
        }
    }

    if (trans != NULL && trans->status == TRANS_STATUS_UP &&
            trans->sck >= 0 && rdp != NULL)
    {
        /* Only send the error info PDU if the client has
